Method.Implementation:
Set tStatus = $$$OK
Try {
	If '$IsObject($get(pBatch)) Set tStatus = $$$ERROR($$$ObjectInstanceRequired) Quit
	If '$IsObject(pIOStream) {
		Set tFilename = pIOStream
		Set pIOStream = ##class(%IO.FileStream).%New()
		Do pIOStream.Open(tFilename,"WAE",,"UTF-8",.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.RecordA) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecA).PutObject(pIOStream,pBatch.RecordA,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.RecordC) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecC).PutObject(pIOStream,pBatch.RecordC,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.RecordE) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecE).PutObject(pIOStream,pBatch.RecordE,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.RecordH) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecH).PutObject(pIOStream,pBatch.RecordH,0)
		If $$$ISERR(tStatus) Quit
	}
	Set seqKey = ""
	For {
		Set tElement = pBatch.RecordN.GetNext(.seqKey)
		If (seqKey = "") Quit
		If $IsObject(tElement) {
			Set tStatus = tElement.PutSequence(pIOStream)
			If $$$ISERR(tStatus) Quit
		}
		Set tStatus = pBatch.RecordN.%UnSwizzleAt(seqKey)
		If $$$ISERR(tStatus) Quit
	}
	If $$$ISERR(tStatus) Quit
	If $IsObject(pBatch.RecordCLMF) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecCLMF).PutObject(pIOStream,pBatch.RecordCLMF,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.RecordCLCC) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecCLCC).PutObject(pIOStream,pBatch.RecordCLCC,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.RecordCDCC) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecCDCC).PutObject(pIOStream,pBatch.RecordCDCC,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.RecordCCDC) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecCCDC).PutObject(pIOStream,pBatch.RecordCCDC,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.RecordCLRC) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecCLRC).PutObject(pIOStream,pBatch.RecordCLRC,0)
		If $$$ISERR(tStatus) Quit
	}
	Set seqKey = ""
	For {
		Set tElement = pBatch.RecordP.GetNext(.seqKey)
		If (seqKey = "") Quit
		If $IsObject(tElement) {
			Set tStatus = tElement.PutSequence(pIOStream)
			If $$$ISERR(tStatus) Quit
		}
		Set tStatus = pBatch.RecordP.%UnSwizzleAt(seqKey)
		If $$$ISERR(tStatus) Quit
	}
	If $$$ISERR(tStatus) Quit
	If $IsObject(pBatch.RecordS) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecS).PutObject(pIOStream,pBatch.RecordS,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.RecordU) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecU).PutObject(pIOStream,pBatch.RecordU,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.RecordCLRN) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecCLRN).PutObject(pIOStream,pBatch.RecordCLRN,0)
		If $$$ISERR(tStatus) Quit
	}
	Set seqKey = ""
	For {
		Set tElement = pBatch.LineLevel.GetNext(.seqKey)
		If (seqKey = "") Quit
		If $IsObject(tElement) {
			Set tStatus = tElement.PutSequence(pIOStream)
			If $$$ISERR(tStatus) Quit
		}
		Set tStatus = pBatch.LineLevel.%UnSwizzleAt(seqKey)
		If $$$ISERR(tStatus) Quit
	}
	If $$$ISERR(tStatus) Quit
	Do pIOStream.Flush(.tStatus)
	If $$$ISERR(tStatus) Quit
} Catch ex {
	Set tStatus = $$$SystemError
}
Quit tStatus

Set tStatus = $$$OK
