		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecA).GetObject(pIOStream,.tObject,pTimeout,.pLookAhead)
		If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexBasic,"RecordA","IHC.ITF.DStruc.ShKeyWordRecA",$classname()),tStatus) Quit
