	}
	Set tCount = 0
	While ($extract(pLookAhead,1,4)="RecN") {
		Set tStatus = ..getSeqRecordN(pIOStream,.tSequence,.pLookAhead,pBatch,pTimeout)
		Set tCount = tCount + 1
		If $$$ISERR(tStatus) Quit
		If (50 < tCount) {
